H.background();
const m1 = P.m1, m2 = P.m2, u1 = P.u1;
const u2 = 0.0;
const s = m1 + m2;
const vf = (m1 * u1 + m2 * u2) / s;
const KEi = 0.5 * m1 * u1 * u1 + 0.5 * m2 * u2 * u2;
const KEf = 0.5 * s * vf * vf;
const lost = KEi - KEf;
const lostPct = KEi > 0.0001 ? 100 * lost / KEi : 0;
H.text("Perfectly Inelastic Collision:  they stick, move together", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("v_f = (m1*u1 + m2*u2)/(m1+m2);  p conserved but KE is LOST to heat/deformation", 24, 52, { color: H.colors.sub, size: 13 });
const cx = 430, trackY = 235, halfW = 380;
H.line(cx - halfW, trackY + 32, cx + halfW, trackY + 32, { color: H.colors.grid, width: 2 });
const period = 6;
const ph = (t % period) / period;
const collide = 0.5;
const w1 = 30 + 9 * m1, w2 = 30 + 9 * m2;
let x1, x2, sv;
const startSep = 200;
if (ph < collide) {
  const f = ph / collide;
  x1 = cx - startSep + u1 * 24 * f;
  x2 = cx + 60;
  sv = u1;
} else {
  const f = (ph - collide) / (1 - collide);
  const cx1 = cx - startSep + u1 * 24 * collide;
  x1 = cx1 + vf * 24 * f;
  x2 = x1 + w1 / 2 + w2 / 2;
  sv = vf;
}
H.rect(x1 - w1 / 2, trackY, w1, 34, { fill: H.colors.accent, stroke: H.colors.ink, width: 2, radius: 4 });
H.rect(x2 - w2 / 2, trackY, w2, 34, { fill: H.colors.violet, stroke: H.colors.ink, width: 2, radius: 4 });
H.arrow((x1 + x2) / 2, trackY + 17, (x1 + x2) / 2 + sv * 16, trackY + 17, { color: H.colors.warn, width: 3 });
H.text("m1 = " + m1.toFixed(1), x1 - w1 / 2, trackY - 10, { color: H.colors.accent, size: 12 });
H.text("m2 = " + m2.toFixed(1), x2 - w2 / 2, trackY - 10, { color: H.colors.violet, size: 12 });
const phase = ph < collide ? "BEFORE  (m1 moving at u1)" : "AFTER  (stuck together at v_f)";
H.text(phase, 24, 348, { color: H.colors.good, size: 14, weight: 700 });
H.text("u1 = " + u1.toFixed(1) + " m/s,  u2 = 0  =>  v_f = " + vf.toFixed(2) + " m/s", 24, 374, { color: H.colors.accent, size: 13 });
H.text("p: " + (m1*u1).toFixed(2) + " = " + (s*vf).toFixed(2) + " kg*m/s  (conserved)", 24, 398, { color: H.colors.sub, size: 13 });
H.text("KE: " + KEi.toFixed(2) + " -> " + KEf.toFixed(2) + " J   lost " + lost.toFixed(2) + " J (" + lostPct.toFixed(0) + "%)", 24, 422, { color: H.colors.warn, size: 13, weight: 700 });
